//! UniFFI wrapper over poly-engine for the Swift macOS app (role 4).
//!
//! Proc-macro style (no UDL). These types mirror poly-engine's but use only
//! FFI-friendly fields (owned strings, byte vectors). Swift bindings are
//! generated by `scripts/build-xcframework.sh` into the `PolyphoniaCore` module.

use std::sync::LazyLock;

use poly_ai::{AiError, LocalServer, Script, ServerKind};
use poly_engine::{Engine, poly_core};

uniffi::setup_scaffolding!();

/// One engine for the process; it is stateless and thread-safe.
static ENGINE: LazyLock<Engine> = LazyLock::new(Engine::default);

/// Encryption algorithm.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum Algorithm {
    /// ML-KEM-768, post-quantum.
    MlKem768,
    /// RSA-2048-OAEP, for comparison.
    Rsa2048,
    /// Testing only. NOT SECURE.
    Fake,
}

/// Carrier file type.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum CarrierKind {
    RawDebug,
    StealthPng,
    RobustPng,
    MusicWav,
    MusicMidi,
}

/// Which slot opened. The UI must look identical for both.
#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum Slot {
    A,
    B,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum AiServerKind {
    LmStudio,
    Ollama,
    Custom,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct AiServer {
    pub kind: AiServerKind,
    pub base_url: String,
    pub models: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, uniffi::Enum)]
pub enum AiScript {
    Latin,
    Georgian,
    Cyrillic,
    Unknown,
}

#[derive(Debug, Clone, PartialEq, uniffi::Record)]
pub struct AiShortenSuggestion {
    pub text: String,
    pub original_bytes: u64,
    pub new_bytes: u64,
    pub saved_percent: f64,
}

#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct AiDecoySuggestion {
    pub text: String,
    pub fits: bool,
    pub min_bytes: u64,
    pub max_bytes: u64,
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error, uniffi::Error)]
pub enum AiFfiError {
    #[error("no local AI server is running")]
    NoLocalServer,
    #[error("not a local server URL: {message}")]
    NotLocal { message: String },
    #[error("the local AI server took too long to answer")]
    Timeout,
    #[error("the local AI server sent an unusable answer")]
    BadResponse,
    #[error("the local AI server failed (HTTP status {status})")]
    ServerFailed { status: u16 },
    #[error("the local AI server returned an error: {message}")]
    Server { message: String },
    #[error("invalid AI request: {message}")]
    InvalidRequest { message: String },
    #[error("the suggestion failed its checks: {}", reasons.join(", "))]
    Rejected { reasons: Vec<String> },
}

impl From<AiError> for AiFfiError {
    fn from(error: AiError) -> Self {
        match error {
            AiError::NoLocalServer => Self::NoLocalServer,
            AiError::NotLocal(message) => Self::NotLocal { message },
            AiError::Timeout => Self::Timeout,
            AiError::BadResponse => Self::BadResponse,
            AiError::ServerFailed { status } => Self::ServerFailed { status },
            AiError::Server(message) => Self::Server { message },
            AiError::InvalidRequest(message) => Self::InvalidRequest { message },
            AiError::Rejected { reasons } => Self::Rejected { reasons },
        }
    }
}

impl From<AiServerKind> for ServerKind {
    fn from(kind: AiServerKind) -> Self {
        match kind {
            AiServerKind::LmStudio => Self::LmStudio,
            AiServerKind::Ollama => Self::Ollama,
            AiServerKind::Custom => Self::Custom,
        }
    }
}

impl From<ServerKind> for AiServerKind {
    fn from(kind: ServerKind) -> Self {
        match kind {
            ServerKind::LmStudio => Self::LmStudio,
            ServerKind::Ollama => Self::Ollama,
            ServerKind::Custom => Self::Custom,
        }
    }
}

impl From<AiScript> for Script {
    fn from(script: AiScript) -> Self {
        match script {
            AiScript::Latin => Self::Latin,
            AiScript::Georgian => Self::Georgian,
            AiScript::Cyrillic => Self::Cyrillic,
            AiScript::Unknown => Self::Unknown,
        }
    }
}

impl From<Script> for AiScript {
    fn from(script: Script) -> Self {
        match script {
            Script::Latin => Self::Latin,
            Script::Georgian => Self::Georgian,
            Script::Cyrillic => Self::Cyrillic,
            Script::Unknown => Self::Unknown,
        }
    }
}

impl From<AiServer> for LocalServer {
    fn from(server: AiServer) -> Self {
        Self {
            kind: server.kind.into(),
            base_url: server.base_url,
            models: server.models,
        }
    }
}

#[uniffi::export]
pub fn ai_detect_servers() -> Vec<AiServer> {
    poly_ai::detect_servers()
        .into_iter()
        .map(|server| AiServer {
            kind: server.kind.into(),
            base_url: server.base_url,
            models: server.models,
        })
        .collect()
}

#[uniffi::export]
pub fn ai_detect_script(text: String) -> AiScript {
    poly_ai::detect_script(&text).into()
}

#[uniffi::export]
pub fn ai_shorten(
    server: AiServer,
    model: String,
    text: String,
) -> Result<AiShortenSuggestion, AiFfiError> {
    let suggestion = poly_ai::shorten(&server.into(), &model, &text)?;
    Ok(AiShortenSuggestion {
        text: suggestion.text,
        original_bytes: suggestion.original_bytes as u64,
        new_bytes: suggestion.new_bytes as u64,
        saved_percent: suggestion.saved_percent,
    })
}

#[uniffi::export]
pub fn ai_generate_decoy(
    server: AiServer,
    model: String,
    target_text_len_bytes: u64,
    script: AiScript,
    tone: Option<String>,
) -> Result<AiDecoySuggestion, AiFfiError> {
    let target =
        usize::try_from(target_text_len_bytes).map_err(|_| AiFfiError::InvalidRequest {
            message: "target length out of range".into(),
        })?;
    let suggestion = poly_ai::generate_decoy(&server.into(), &model, target, script.into(), tone)?;
    Ok(AiDecoySuggestion {
        text: suggestion.text,
        fits: suggestion.fits,
        min_bytes: suggestion.allowed_len_range.0 as u64,
        max_bytes: suggestion.allowed_len_range.1 as u64,
    })
}

/// A key pair. Store `secret_key` in the Keychain.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct Identity {
    pub public_key: Vec<u8>,
    pub secret_key: Vec<u8>,
}

/// Carrier-specific options; all optional.
#[derive(Debug, Clone, Default, PartialEq, Eq, uniffi::Record)]
pub struct CarrierOptions {
    #[uniffi(default = None)]
    pub cover_image: Option<Vec<u8>>,
    #[uniffi(default = None)]
    pub cover_audio: Option<Vec<u8>>,
    #[uniffi(default = None)]
    pub music_style: Option<String>,
    #[uniffi(default = None)]
    pub seed: Option<u64>,
}

/// What to encrypt and how. Hidden mode = both `decoy` and `passphrase` set.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct EncryptRequest {
    pub message: String,
    #[uniffi(default = None)]
    pub decoy: Option<String>,
    #[uniffi(default = None)]
    pub passphrase: Option<String>,
    pub recipient_public_key: Vec<u8>,
    pub algorithm: Algorithm,
    pub carrier: CarrierKind,
    pub options: CarrierOptions,
    /// None sends a full message and starts a new session.
    #[uniffi(default = None)]
    pub session_key: Option<Vec<u8>>,
}

/// A finished carrier file.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct EncodedFile {
    pub bytes: Vec<u8>,
    /// Without the dot, e.g. "png".
    pub extension: String,
    pub mime: String,
    pub carrier: CarrierKind,
    pub algorithm: Algorithm,
    pub session_key: Option<Vec<u8>>,
}

/// A received file to open.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct DecryptRequest {
    pub file: Vec<u8>,
    pub my_secret_key: Vec<u8>,
    pub my_public_key: Vec<u8>,
    #[uniffi(default = None)]
    pub passphrase: Option<String>,
    #[uniffi(default = [])]
    pub session_keys: Vec<Vec<u8>>,
}

/// The opened message.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct Decrypted {
    pub text: String,
    pub slot: Slot,
    pub carrier: CarrierKind,
    pub algorithm: Algorithm,
    pub session_key: Option<Vec<u8>>,
}

/// Header information readable without a key.
#[derive(Debug, Clone, PartialEq, Eq, uniffi::Record)]
pub struct Inspected {
    pub carrier: CarrierKind,
    pub algorithm: Algorithm,
    pub contact_id: Vec<u8>,
    pub payload_len: u64,
    pub is_session: bool,
}

/// Every error the core can return. Messages never contain secrets.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error, uniffi::Error)]
pub enum PolyError {
    #[error("not a Polyphonia envelope")]
    BadMagic,
    #[error("unsupported envelope version {version}")]
    UnsupportedVersion { version: u8 },
    #[error("unknown algorithm id {id}")]
    UnknownAlgorithm { id: u8 },
    #[error("reserved flag bits set: {flags}")]
    ReservedFlags { flags: u8 },
    #[error("data is truncated")]
    Truncated,
    /// The file was damaged in transit, typically by messenger recompression.
    /// Show: "compressed in transit, ask them to resend as a document".
    #[error("checksum mismatch: the file was damaged or compressed in transit")]
    ChecksumMismatch,
    #[error("payload too large: {len} bytes")]
    PayloadTooLarge { len: u64 },
    #[error("malformed payload: {reason}")]
    MalformedPayload { reason: String },
    #[error("message too long: {len} bytes (max {max})")]
    MessageTooLong { len: u64, max: u64 },
    #[error("hidden mode needs a passphrase")]
    MissingPassphrase,
    #[error("invalid request: {reason}")]
    InvalidRequest { reason: String },
    #[error("invalid key: {reason}")]
    InvalidKey { reason: String },
    #[error("decryption failed")]
    DecryptFailed,
    #[error("this message is not addressed to this key")]
    WrongRecipient,
    /// A session message whose session was never started on this device.
    /// Show: "ask them to send a full message first".
    #[error("unknown session: ask the sender to send a full message first")]
    UnknownSession,
    #[error("crypto error: {reason}")]
    Crypto { reason: String },
    #[error("file is not in this carrier's format")]
    NotThisCarrier,
    #[error("carrier too small: need {needed} bytes, carrier holds {available}")]
    CarrierTooSmall { needed: u64, available: u64 },
    #[error("no carrier recognized this file")]
    UnrecognizedFile,
    #[error("carrier error: {reason}")]
    Carrier { reason: String },
    #[error("not implemented yet: {what}")]
    NotImplemented { what: String },
}

// ---- Conversions ------------------------------------------------------------

impl From<poly_core::PolyError> for PolyError {
    fn from(e: poly_core::PolyError) -> Self {
        use poly_core::PolyError as E;
        let n = |v: usize| v as u64;
        match e {
            E::BadMagic => Self::BadMagic,
            E::UnsupportedVersion(version) => Self::UnsupportedVersion { version },
            E::UnknownAlgorithm(id) => Self::UnknownAlgorithm { id },
            E::ReservedFlags(flags) => Self::ReservedFlags { flags },
            E::Truncated => Self::Truncated,
            E::ChecksumMismatch => Self::ChecksumMismatch,
            E::PayloadTooLarge(len) => Self::PayloadTooLarge { len: n(len) },
            E::MalformedPayload(r) => Self::MalformedPayload { reason: r.into() },
            E::MessageTooLong { len, max } => Self::MessageTooLong {
                len: n(len),
                max: n(max),
            },
            E::MissingPassphrase => Self::MissingPassphrase,
            E::InvalidRequest(r) => Self::InvalidRequest { reason: r.into() },
            E::InvalidKey(r) => Self::InvalidKey { reason: r.into() },
            E::DecryptFailed => Self::DecryptFailed,
            E::WrongRecipient => Self::WrongRecipient,
            E::UnknownSession => Self::UnknownSession,
            E::Crypto(reason) => Self::Crypto { reason },
            E::NotThisCarrier => Self::NotThisCarrier,
            E::CarrierTooSmall { needed, available } => Self::CarrierTooSmall {
                needed: n(needed),
                available: n(available),
            },
            E::UnrecognizedFile => Self::UnrecognizedFile,
            E::Carrier(reason) => Self::Carrier { reason },
            E::NotImplemented(what) => Self::NotImplemented { what: what.into() },
        }
    }
}

impl From<Algorithm> for poly_core::Algorithm {
    fn from(a: Algorithm) -> Self {
        match a {
            Algorithm::MlKem768 => Self::MlKem768,
            Algorithm::Rsa2048 => Self::Rsa2048,
            Algorithm::Fake => Self::Fake,
        }
    }
}

impl From<poly_core::Algorithm> for Algorithm {
    fn from(a: poly_core::Algorithm) -> Self {
        match a {
            poly_core::Algorithm::MlKem768 => Self::MlKem768,
            poly_core::Algorithm::Rsa2048 => Self::Rsa2048,
            poly_core::Algorithm::Fake => Self::Fake,
        }
    }
}

impl From<CarrierKind> for poly_core::CarrierKind {
    fn from(c: CarrierKind) -> Self {
        match c {
            CarrierKind::RawDebug => Self::RawDebug,
            CarrierKind::StealthPng => Self::StealthPng,
            CarrierKind::RobustPng => Self::RobustPng,
            CarrierKind::MusicWav => Self::MusicWav,
            CarrierKind::MusicMidi => Self::MusicMidi,
        }
    }
}

impl From<poly_core::CarrierKind> for CarrierKind {
    fn from(c: poly_core::CarrierKind) -> Self {
        match c {
            poly_core::CarrierKind::RawDebug => Self::RawDebug,
            poly_core::CarrierKind::StealthPng => Self::StealthPng,
            poly_core::CarrierKind::RobustPng => Self::RobustPng,
            poly_core::CarrierKind::MusicWav => Self::MusicWav,
            poly_core::CarrierKind::MusicMidi => Self::MusicMidi,
        }
    }
}

impl From<poly_core::Slot> for Slot {
    fn from(s: poly_core::Slot) -> Self {
        match s {
            poly_core::Slot::A => Self::A,
            poly_core::Slot::B => Self::B,
        }
    }
}

impl From<CarrierOptions> for poly_core::CarrierOptions {
    fn from(o: CarrierOptions) -> Self {
        Self {
            cover_image: o.cover_image,
            cover_audio: o.cover_audio,
            music_style: o.music_style,
            seed: o.seed,
        }
    }
}

// ---- Exported functions -----------------------------------------------------

/// Generate a new key pair.
#[uniffi::export]
pub fn generate_identity(algorithm: Algorithm) -> Result<Identity, PolyError> {
    let id = ENGINE.generate_identity(algorithm.into())?;
    Ok(Identity {
        public_key: id.public_key,
        secret_key: id.secret_key,
    })
}

/// First 8 bytes of SHA-256(public key): identifies a contact.
#[uniffi::export]
pub fn contact_id(public_key: Vec<u8>) -> Vec<u8> {
    poly_engine::contact_id(&public_key).to_vec()
}

/// Validate an imported public key through its cipher before saving the contact.
/// A discarded empty full message exercises the cipher's complete key parser.
#[uniffi::export]
pub fn validate_public_key(public_key: Vec<u8>, algorithm: Algorithm) -> Result<(), PolyError> {
    ENGINE.encrypt(&poly_engine::EncryptRequest {
        message: String::new(),
        decoy: None,
        passphrase: None,
        recipient_public_key: public_key,
        algorithm: algorithm.into(),
        carrier: poly_core::CarrierKind::RawDebug,
        options: Default::default(),
        session_key: None,
    })?;
    Ok(())
}

/// Stable id for a session key, for Keychain indexing. Never logs the key.
#[uniffi::export]
pub fn session_id(session_key: Vec<u8>) -> Result<Vec<u8>, PolyError> {
    Ok(poly_core::SessionKey::try_from(session_key.as_slice())?
        .id()
        .to_vec())
}

/// Encrypt a message into a carrier file.
#[uniffi::export]
pub fn encrypt(request: EncryptRequest) -> Result<EncodedFile, PolyError> {
    let file = ENGINE.encrypt(&poly_engine::EncryptRequest {
        message: request.message,
        decoy: request.decoy,
        passphrase: request.passphrase,
        recipient_public_key: request.recipient_public_key,
        algorithm: request.algorithm.into(),
        carrier: request.carrier.into(),
        options: request.options.into(),
        session_key: request
            .session_key
            .as_deref()
            .map(poly_core::SessionKey::try_from)
            .transpose()?,
    })?;
    Ok(EncodedFile {
        bytes: file.bytes,
        extension: file.extension.into(),
        mime: file.mime.into(),
        carrier: file.carrier.into(),
        algorithm: file.algorithm.into(),
        session_key: file.session_key.map(|key| key.as_bytes().to_vec()),
    })
}

/// Auto-detect the carrier and open the message.
#[uniffi::export]
pub fn decrypt(request: DecryptRequest) -> Result<Decrypted, PolyError> {
    let d = ENGINE.decrypt(&poly_engine::DecryptRequest {
        file: request.file,
        my_secret_key: request.my_secret_key,
        my_public_key: request.my_public_key,
        passphrase: request.passphrase,
        session_keys: request
            .session_keys
            .iter()
            .map(|bytes| poly_core::SessionKey::try_from(bytes.as_slice()))
            .collect::<Result<_, _>>()?,
    })?;
    Ok(Decrypted {
        text: d.text,
        slot: d.slot.into(),
        carrier: d.carrier.into(),
        algorithm: d.algorithm.into(),
        session_key: d.session_key.map(|key| key.as_bytes().to_vec()),
    })
}

/// Detect the carrier and read the envelope header, without a key.
#[uniffi::export]
pub fn inspect(file: Vec<u8>) -> Result<Inspected, PolyError> {
    let i = ENGINE.inspect(&file)?;
    Ok(Inspected {
        carrier: i.carrier.into(),
        is_session: i.envelope.is_session(),
        algorithm: i.envelope.algorithm.into(),
        contact_id: i.envelope.contact_id.to_vec(),
        payload_len: i.envelope.payload.len() as u64,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roundtrip_through_ffi_types() {
        let me = generate_identity(Algorithm::Fake).unwrap();
        let file = encrypt(EncryptRequest {
            message: "real".into(),
            decoy: Some("decoy".into()),
            passphrase: Some("pw".into()),
            recipient_public_key: me.public_key.clone(),
            algorithm: Algorithm::Fake,
            carrier: CarrierKind::RawDebug,
            options: CarrierOptions::default(),
            session_key: None,
        })
        .unwrap();
        assert_eq!(file.extension, "bin");

        let open = |passphrase: Option<&str>| {
            decrypt(DecryptRequest {
                file: file.bytes.clone(),
                my_secret_key: me.secret_key.clone(),
                my_public_key: me.public_key.clone(),
                passphrase: passphrase.map(Into::into),
                session_keys: Vec::new(),
            })
        };
        let b = open(Some("pw")).unwrap();
        assert_eq!((b.text.as_str(), b.slot), ("real", Slot::B));
        let a = open(None).unwrap();
        assert_eq!((a.text.as_str(), a.slot), ("decoy", Slot::A));

        let i = inspect(file.bytes.clone()).unwrap();
        assert_eq!(i.contact_id, contact_id(me.public_key.clone()));
        assert_eq!(i.algorithm, Algorithm::Fake);
    }

    #[test]
    fn rejects_malformed_session_keys_at_the_ffi_boundary() {
        assert!(matches!(
            session_id(vec![0]),
            Err(PolyError::InvalidKey { .. })
        ));
        let me = generate_identity(Algorithm::MlKem768).unwrap();
        let request = EncryptRequest {
            message: "test".into(),
            decoy: None,
            passphrase: None,
            recipient_public_key: me.public_key.clone(),
            algorithm: Algorithm::MlKem768,
            carrier: CarrierKind::RawDebug,
            options: CarrierOptions::default(),
            session_key: Some(vec![0]),
        };
        assert!(matches!(
            encrypt(request.clone()),
            Err(PolyError::InvalidKey { .. })
        ));
        let full = encrypt(EncryptRequest {
            session_key: None,
            ..request
        })
        .unwrap();
        let key = full.session_key.as_ref().unwrap();
        assert_eq!(
            session_id(key.clone()).unwrap().len(),
            poly_core::payload::SESSION_ID_LEN
        );
        assert!(matches!(
            decrypt(DecryptRequest {
                file: full.bytes,
                my_public_key: me.public_key,
                my_secret_key: me.secret_key,
                passphrase: None,
                session_keys: vec![vec![0]],
            }),
            Err(PolyError::InvalidKey { .. })
        ));
    }

    #[test]
    fn errors_map() {
        let mut bytes = encrypt(EncryptRequest {
            message: "x".into(),
            decoy: None,
            passphrase: None,
            recipient_public_key: generate_identity(Algorithm::Fake).unwrap().public_key,
            algorithm: Algorithm::Fake,
            carrier: CarrierKind::RawDebug,
            options: CarrierOptions::default(),
            session_key: None,
        })
        .unwrap()
        .bytes;
        bytes[25] ^= 1;
        assert_eq!(inspect(bytes), Err(PolyError::ChecksumMismatch));
    }
}
